import { test, expect } from '@playwright/test';
import type { Locator, Page } from '@playwright/test';

// Story 18-S2 — Two greens.
//
// Two new palette variables, `green-faint` (#F0F5E5) and `green-faint-hover`
// (#EAF0DB), and two color styles referencing them, `puzzle-row-play` and
// `puzzle-row-play-hover`, mirroring `puzzle-row` and `puzzle-row-hover`.
// All four are shown in the style guide's catalog. No component uses the
// styles yet (S3 is their first user). Colors are the human's values written
// out, not read from the styles. Do not edit this file to match an
// implementation.

type Rgba = { r: number; g: number; b: number; a: number };

const GREENS: Record<string, string> = {
  'green-faint': '#F0F5E5',
  'green-faint-hover': '#EAF0DB',
};

// style -> the variable it references
const PLAY_ROW_STYLES: Record<string, string> = {
  'puzzle-row-play': 'green-faint',
  'puzzle-row-play-hover': 'green-faint-hover',
};

const SENTINEL = '#123456';

/** The forms getComputedStyle reports for a colour: rgb(), rgba() and color(srgb ...). */
function parseColor(value: string): Rgba {
  const rgb = value.match(/^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/);
  if (rgb) return { r: Number(rgb[1]), g: Number(rgb[2]), b: Number(rgb[3]), a: alpha(rgb[4]) };
  const srgb = value.match(/^color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\s*\)$/);
  if (srgb) {
    return {
      r: Math.round(Number(srgb[1]) * 255),
      g: Math.round(Number(srgb[2]) * 255),
      b: Math.round(Number(srgb[3]) * 255),
      a: alpha(srgb[4]),
    };
  }
  throw new Error(`unparseable colour: "${value}"`);
}

function alpha(raw: string | undefined) {
  if (raw === undefined) return 1;
  return raw.endsWith('%') ? Number(raw.slice(0, -1)) / 100 : Number(raw);
}

function hexToRgba(hex: string): Rgba {
  const n = parseInt(hex.replace('#', ''), 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255, a: 1 };
}

function expectColor(actual: Rgba, expected: Rgba, label: string) {
  expect({ r: actual.r, g: actual.g, b: actual.b }, label).toEqual({ r: expected.r, g: expected.g, b: expected.b });
  expect(actual.a, `${label} alpha`).toBeCloseTo(expected.a, 2);
}

/** The colour a CSS value paints as a background on this page. */
async function resolve(page: Page, cssValue: string) {
  return parseColor(
    await page.evaluate((value) => {
      const probe = document.createElement('div');
      probe.style.backgroundColor = value;
      document.body.appendChild(probe);
      const resolved = getComputedStyle(probe).backgroundColor;
      probe.remove();
      return resolved;
    }, cssValue)
  );
}

async function bgOf(locator: Locator) {
  return parseColor(await locator.evaluate((el) => getComputedStyle(el).backgroundColor));
}

/** The declared value of a variable on :root, as written in the stylesheet. */
function rootVariable(page: Page, name: string) {
  return page.evaluate((n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim(), name);
}

test.describe('18-S2-1 green-faint and green-faint-hover are palette variables', () => {
  test('each holds the human value and is shown in the catalog by name and hex', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-colors')).toBeVisible();

    for (const [name, hex] of Object.entries(GREENS)) {
      expect((await rootVariable(page, `--palette-${name}`)).toLowerCase(), `--palette-${name}`).toBe(
        hex.toLowerCase()
      );
      expectColor(await resolve(page, `var(--palette-${name})`), hexToRgba(hex), `--palette-${name}`);

      const row = page.locator(`[data-testid="sg-color-variable"][data-variable="${name}"]`);
      await expect(row, `a catalog row for ${name}`).toBeVisible();
      await expect(row).toContainText(name);
      await expect(row).toContainText(new RegExp(hex.replace('#', ''), 'i'));
      expectColor(await bgOf(row.getByTestId('sg-swatch')), hexToRgba(hex), `${name} swatch`);
    }
  });
});

test.describe('18-S2-2 puzzle-row-play and puzzle-row-play-hover reference the greens', () => {
  test('each style resolves to its green and follows it when the variable is edited live', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-colors')).toBeVisible();

    for (const [style, variable] of Object.entries(PLAY_ROW_STYLES)) {
      const hex = GREENS[variable];
      expectColor(await resolve(page, `var(--color-${style})`), hexToRgba(hex), `--color-${style}`);

      await page.evaluate(([n, v]) => document.documentElement.style.setProperty(n, v), [
        `--palette-${variable}`,
        SENTINEL,
      ] as const);
      expectColor(
        await resolve(page, `var(--color-${style})`),
        hexToRgba(SENTINEL),
        `--color-${style} after editing --palette-${variable}`
      );
      await page.evaluate((n) => document.documentElement.style.removeProperty(n), `--palette-${variable}`);
      expectColor(await resolve(page, `var(--color-${style})`), hexToRgba(hex), `--color-${style} restored`);
    }
  });

  test('the play row styles differ from each other and from puzzle-row and puzzle-row-hover', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-colors')).toBeVisible();

    const colors = await Promise.all(
      ['puzzle-row', 'puzzle-row-hover', 'puzzle-row-play', 'puzzle-row-play-hover'].map(async (style) =>
        JSON.stringify(await resolve(page, `var(--color-${style})`))
      )
    );
    expect(new Set(colors).size, 'four distinct row colors').toBe(4);
  });

  test('each style is shown in the catalog with its variable, swatched in its green', async ({ page }) => {
    await page.goto('/style-guide');
    await expect(page.getByTestId('sg-colors')).toBeVisible();

    for (const [style, variable] of Object.entries(PLAY_ROW_STYLES)) {
      const row = page.locator(`[data-testid="sg-color-style"][data-style="${style}"]`);
      await expect(row, `a catalog row for ${style}`).toBeVisible();
      await expect(row).toContainText(style);
      await expect(row).toContainText(variable);
      expectColor(await bgOf(row.getByTestId('sg-swatch')), hexToRgba(GREENS[variable]), `${style} swatch`);
    }
  });
});
